"""Generate the blind validation labeling tool as a single self-contained HTML
file from a holdout sample (produced by make_holdout_sample.py).

The labeler UI (kept identical across rounds so labels are comparable) is embedded
below; the taxonomy shown to the labeler is rebuilt from the canonical taxonomy
files, and the country list from pycountry, so this one script reproduces the
tool for any sample. Open the HTML in a browser, label blind, and use its export
button to download the labels CSV. Labels are not produced here.

    uv run python validation/make_labeling_tool.py \\
        --sample validation/holdout_sample.json \\
        --key ghrm_holdout_2026 --out validation/labeling_tool.html
"""
import argparse
import base64
import csv
import json
from collections import OrderedDict
from pathlib import Path

import pycountry

ROOT = Path(__file__).resolve().parent.parent
TAX = ROOT / "data" / "taxonomy"

# Labeler UI shell (HTML/CSS/JS), base64 so no escaping issues. The classified
# sample is injected between HEAD and TAIL as `const B={...}`.
HEAD = base64.b64decode("").decode("utf-8")
TAIL = base64.b64decode("").decode("utf-8")


def build_cats():
    cats = OrderedDict()
    for r in csv.DictReader(open(TAX / "topic_taxonomy.csv")):
        c = cats.setdefault(r["category_letter"],
                            {"letter": r["category_letter"], "name": r["category_name"], "subs": []})
        c["subs"].append({"id": r["subtopic_id"], "name": r["subtopic_name"]})
    out = list(cats.values())
    out.append({"letter": "Z", "name": "Uncategorized / none fits",
                "subs": [{"id": "Z00", "name": "Uncategorized"}]})
    return out


def build_methods():
    return [{"id": r["method_id"], "name": r["method_name"]}
            for r in csv.DictReader(open(TAX / "methods_taxonomy.csv"))]


def build_countries():
    return sorted(({"code": c.alpha_2, "name": c.name} for c in pycountry.countries),
                  key=lambda x: x["name"])


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--sample", required=True, help="holdout_sample.json from make_holdout_sample.py")
    ap.add_argument("--out", default="validation/labeling_tool.html")
    ap.add_argument("--key", default="ghrm_holdout_v1",
                    help="localStorage namespace so rounds do not collide")
    args = ap.parse_args()

    papers = json.loads(Path(args.sample).read_text())
    B = {"papers": papers, "cats": build_cats(),
         "methods": build_methods(), "countries": build_countries()}
    html = HEAD + "\nconst B=" + json.dumps(B, ensure_ascii=False) + ";\n" + TAIL
    html = html.replace("const KEY='ghrm_sealed_v1'", "const KEY='" + args.key + "'")
    Path(args.out).write_text(html)
    print("wrote " + args.out + ": " + str(len(papers)) + " papers, key=" + args.key)


if __name__ == "__main__":
    main()
